		public virtual int GetStreamInfo(object FileNode, object FileDesc, IntPtr Buffer, uint Length, out uint BytesTransferred)
		{
			object Context = null;
			StreamInfo StreamInfo = default;
			BytesTransferred = 0u;
			string StreamName;
			while (GetStreamEntry(FileNode, FileDesc, ref Context, out StreamName, out StreamInfo.StreamSize, out StreamInfo.StreamAllocationSize))
