		public int SeekableReadDirectory(object FileNode, object FileDesc, string Pattern, string Marker, IntPtr Buffer, uint Length, out uint BytesTransferred)
		{
			object Context = null;
			DirInfo DirInfo = default;
			BytesTransferred = 0u;
			string FileName;
			while (ReadDirectoryEntry(FileNode, FileDesc, Pattern, Marker, ref Context, out FileName, out DirInfo.FileInfo))
			{
				DirInfo.SetFileNameBuf(FileName);
				if (!Api.FspFileSystemAddDirInfo(ref DirInfo, Buffer, Length, out BytesTransferred))
				{
					return 0;
				}
			}
			Api.FspFileSystemEndDirInfo(Buffer, Length, out BytesTransferred);
			return 0;
		}

		public int BufferedReadDirectory(DirectoryBuffer DirectoryBuffer, object FileNode, object FileDesc, string Pattern, string Marker, IntPtr Buffer, uint Length, out uint BytesTransferred)
		{
			object Context = null;
			DirInfo DirInfo = default;
			int PResult = 0;
			BytesTransferred = 0u;
			if (Api.FspFileSystemAcquireDirectoryBuffer(ref DirectoryBuffer.DirBuffer, Marker == null, out PResult))
			{
				try
				{
					string FileName;
					while (ReadDirectoryEntry(FileNode, FileDesc, Pattern, Marker, ref Context, out FileName, out DirInfo.FileInfo))
					{
						DirInfo.SetFileNameBuf(FileName);
						if (!Api.FspFileSystemFillDirectoryBuffer(ref DirectoryBuffer.DirBuffer, ref DirInfo, out PResult))
						{
							break;
						}
					}
				}
				finally
				{
					Api.FspFileSystemReleaseDirectoryBuffer(ref DirectoryBuffer.DirBuffer);
				}
			}
			if (0 > PResult)
			{
				BytesTransferred = 0u;
				return PResult;
			}
			Api.FspFileSystemReadDirectoryBuffer(ref DirectoryBuffer.DirBuffer, Marker, Buffer, Length, out BytesTransferred);
			return 0;
		}

		/// <summary>
		/// Finds a reparse point in file name.
		/// </summary>
		/// <remarks>
		/// This is a helper for implementing the GetSecurityByName operation in file systems
		/// that support reparse points.
		/// </remarks>
		/// <param name="FileName">
		/// The name of the file or directory.
		/// </param>
		/// <param name="ReparsePointIndex">
		/// Receives the index of the first reparse point within FileName.
		/// </param>
		/// <returns>True if a reparse point was found, false otherwise.</returns>
		/// <seealso cref="M:Fsp.FileSystemBase.GetSecurityByName(System.String,System.UInt32@,System.Byte[]@)" />
		public bool FindReparsePoint(string FileName, out uint ReparsePointIndex)
		{
			GCHandle gCHandle = GCHandle.Alloc(this, GCHandleType.Normal);
			try
			{
				return Api.FspFileSystemFindReparsePoint(IntPtr.Zero, GetReparsePointByName, (IntPtr)gCHandle, FileName, out ReparsePointIndex);
			}
			finally
			{
				gCHandle.Free();
			}
		}

