		/// <summary>
		/// Tests whether reparse data can be replaced.
		/// </summary>
		/// <remarks>
		/// This is a helper for implementing the SetReparsePoint/DeleteReparsePoint operation
		/// in file systems that support reparse points.
		/// </remarks>
		/// <param name="CurrentReparseData">
		/// The current reparse data.
		/// </param>
		/// <param name="ReplaceReparseData">
		/// The replacement reparse data.
		/// </param>
		/// <returns>STATUS_SUCCESS or error code.</returns>
		/// <seealso cref="M:Fsp.FileSystemBase.SetReparsePoint(System.Object,System.Object,System.String,System.Byte[])" />
		/// <seealso cref="M:Fsp.FileSystemBase.DeleteReparsePoint(System.Object,System.Object,System.String,System.Byte[])" />
		public static int CanReplaceReparsePoint(byte[] CurrentReparseData, byte[] ReplaceReparseData)
		{
			return Api.FspFileSystemCanReplaceReparsePoint(CurrentReparseData, ReplaceReparseData);
		}

		private static int GetReparsePointByName(IntPtr FileSystem, IntPtr Context, string FileName, bool IsDirectory, IntPtr Buffer, IntPtr PSize)
		{
			FileSystemBase fileSystemBase = (FileSystemBase)GCHandle.FromIntPtr(Context).Target;
			try
			{
				byte[] ReparseData = null;
				int num = fileSystemBase.GetReparsePointByName(FileName, IsDirectory, ref ReparseData);
				if (0 <= num)
				{
					num = Api.CopyReparsePoint(ReparseData, Buffer, PSize);
				}
				return num;
			}
			catch (Exception ex)
			{
				return fileSystemBase.ExceptionHandler(ex);
			}
		}

