	/// <summary>
	/// Provides the base class for a process that can be run as a service,
	/// command line application or under the control of the WinFsp launcher.
	/// </summary>
	public class Service
	{
		public const uint EVENTLOG_ERROR_TYPE = 1u;

		public const uint EVENTLOG_WARNING_TYPE = 2u;

		public const uint EVENTLOG_INFORMATION_TYPE = 4u;

		private static Api.Proto.ServiceStart _OnStart = OnStart;

		private static Api.Proto.ServiceStop _OnStop = OnStop;

		private IntPtr _ServicePtr;

		/// <summary>
		/// Gets or sets the service process exit code.
		/// </summary>
		public int ExitCode
		{
			get
			{
				if (IntPtr.Zero == _ServicePtr)
				{
					throw new InvalidOperationException();
				}
				return (int)Api.FspServiceGetExitCode(_ServicePtr);
			}
			set
			{
				if (IntPtr.Zero == _ServicePtr)
				{
					throw new InvalidOperationException();
				}
				Api.FspServiceSetExitCode(_ServicePtr, (uint)value);
			}
		}

		public IntPtr ServiceHandle => _ServicePtr;

		/// <summary>
		/// Creates an instance of the Service class.
		/// </summary>
		/// <param name="ServiceName">The name of the service.</param>
		public Service(string ServiceName)
		{
			Api.FspServiceCreate(ServiceName, _OnStart, _OnStop, null, out _ServicePtr);
			if (IntPtr.Zero != _ServicePtr)
			{
				Api.SetUserContext(_ServicePtr, this);
			}
		}

		~Service()
		{
			if (IntPtr.Zero != _ServicePtr)
			{
				Api.DisposeUserContext(_ServicePtr);
				Api.FspServiceDelete(_ServicePtr);
			}
		}

		/// <summary>
		/// Runs a service.
		/// </summary>
		/// <returns>Service process exit code.</returns>
		public int Run()
		{
			if (IntPtr.Zero == _ServicePtr)
			{
				Log(1u, $"The service {GetType().FullName} cannot be created (Status={-1073741670:X}).");
				return (int)Api.FspWin32FromNtStatus(-1073741670);
			}
			Api.FspServiceAllowConsoleMode(_ServicePtr);
			int num = Api.FspServiceLoop(_ServicePtr);
			int result = (int)Api.FspServiceGetExitCode(_ServicePtr);
			if (0 > num)
			{
				Log(1u, $"The service {GetType().FullName} has failed to run (Status={num:X}).");
				return (int)Api.FspWin32FromNtStatus(num);
			}
			return result;
		}

		/// <summary>
		/// Stops a running service.
		/// </summary>
		public void Stop()
		{
			if (IntPtr.Zero == _ServicePtr)
			{
				throw new InvalidOperationException();
			}
			Api.FspServiceStop(_ServicePtr);
		}

		public void RequestTime(uint Time)
		{
			if (IntPtr.Zero == _ServicePtr)
			{
				throw new InvalidOperationException();
			}
			Api.FspServiceRequestTime(_ServicePtr, Time);
		}

		public static void Log(uint Type, string Message)
		{
			Api.FspServiceLog(Type, "%s", Message);
		}

		/// <summary>
		/// Provides a means to customize the returned status code when an exception happens.
		/// </summary>
		/// <param name="ex"></param>
		/// <returns>STATUS_SUCCESS or error code.</returns>
		protected virtual int ExceptionHandler(Exception ex)
		{
			return -532459699;
		}

		/// <summary>
		/// Occurs when the service starts.
		/// </summary>
		/// <param name="Args">Command line arguments passed to the service.</param>
		protected virtual void OnStart(string[] Args)
		{
		}

		/// <summary>
		/// Occurs when the service stops.
		/// </summary>
		protected virtual void OnStop()
		{
		}

		private static int OnStart(IntPtr Service, uint Argc, string[] Argv)
		{
			Service service = (Service)Api.GetUserContext(Service);
			try
			{
				service.OnStart(Argv);
				return 0;
			}
			catch (Exception ex)
			{
				return service.ExceptionHandler(ex);
			}
		}

		private static int OnStop(IntPtr Service)
		{
			Service service = (Service)Api.GetUserContext(Service);
			try
			{
				service.OnStop();
				return 0;
			}
			catch (Exception ex)
			{
				return service.ExceptionHandler(ex);
			}
		}
	}
